// Set constants
const G = 9.81; // acceleration due to gravity (m/s^2)
const M = 1; // mass of the pendulum (kg)
const L = 0.5; // length of the pendulum (m)
const dt = 0.01; // time step (s)

// Initialize variables
let theta = 0; // initial angle (rad)
let omega = 0; // initial angular velocity (rad/s)
let t = 0; // current time (s)
let released = false; // has the pendulum been released?

// Function to update the pendulum's position and velocity
function update() {
  if (released) {
    // Update angular position and velocity using the equations of motion
    omega += (-G / L) * Math.sin(theta) * dt;
    theta += omega * dt;

    // Check if the pendulum has come to rest
    if (Math.abs(omega) < 0.001) {
      released = false;
    }
  }
}

// Function to draw the pendulum
function draw() {
  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw the pendulum
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, L, canvas.height / 2 - L * Math.sin(theta), canvas.height / 2 - L * Math.cos(theta));
  ctx.stroke();

  // Draw the pivot point
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 2, 0, 2 * Math.PI);
  ctx.stroke();

  // Update the canvas
  canvas.requestAnimationFrame(() => {
    draw();
  });
}

