  // Get the initial angle from the input field
  theta = parseFloat(document.getElementById("initial-angle").value) * Math.PI / 180;

  // Set the initial angular velocity to 0
  omega = 0;

  // Set the pendulum as released
  released = true;

  // Start the update and draw functions
  requestAnimationFrame(() => {
    update();
    draw();
  });
}

